fn solve(n: i8, s: Vec<char>) -> i8 {
    if n == 0 {
        return 0;
    }

    let mut x = 0;
    let mut y = 0;
    let mut transitions = 0;
    let mut last_region = None; // None for border, Some(true) for A, Some(false) for B

    for &move_char in &s {
        match move_char {
            'U' => y += 1,
            'R' => x += 1,
            _ => continue, // In case of invalid input, though not expected
        }

        // Determine the current region
        let current_region = if x > y {
            Some(true) // Region A
        } else if y > x {
            Some(false) // Region B
        } else {
            None // Border
        };

        // Count transitions
        if let Some(current) = current_region {
            if let Some(last) = last_region {
                if current != last {
                    transitions += 1; // Transition occurred
                }
            }
            last_region = Some(current);
        } else {
            // If we are on the border, we do not change the last_region
            continue;
        }
    }

    transitions
}